<template>
  <section class="ai-admin"><div class="catalog-heading"><div><p class="eyebrow">AI 问答管理</p><h1>知识库</h1><p class="muted">草稿不影响当前回答。发布须等待索引完成，失败时保留原有效版本。</p></div><button class="primary-button" type="button" @click="newDocument">＋ 新建知识</button></div>
    <form class="ai-filters" @submit.prevent="page = 1; load()"><select v-model="type"><option value="">全部类型</option><option v-for="(label, value) in types" :key="value" :value="value">{{ label }}</option></select><input v-model="keyword" placeholder="搜索知识标题" aria-label="知识标题"><button class="secondary-button">查询</button><button type="button" class="text-action" @click="load">刷新索引状态</button></form><PageStatus :loading="loading" :error="error" :empty="!items?.items.length" empty-text="暂无知识。先准备FAQ或政策资料，无模型也可以发布关键词知识。" @retry="load" />
    <div v-if="items?.items.length" class="table-scroll"><table class="admin-table"><thead><tr><th>知识</th><th>生效状态</th><th>索引</th><th>更新</th><th>操作</th></tr></thead><tbody><tr v-for="item in items.items" :key="item.id"><td><strong>{{ item.title }}</strong><small>{{ types[item.type] }} · {{ item.originKind === 'CATALOG' ? '商品自动同步' : '手工维护' }}</small></td><td>{{ item.enabled && item.activeRevision ? '已生效' : item.enabled ? '待首次发布' : '未启用' }}<small>草稿版本 {{ item.version }}</small></td><td>{{ indexLabel(item.indexStatus) }}<small v-if="item.indexError" class="danger-text">{{ item.indexError }}</small></td><td>{{ date(item.updatedAt) }}</td><td><div class="table-actions"><button type="button" class="text-action" @click="edit(item.id)">查看 / 编辑</button><button v-if="item.activeRevision" type="button" class="text-action" :disabled="busy" @click="toggle(item)">{{ item.enabled ? '停用' : '启用' }}</button><button v-if="item.enabled && item.latestRevision && item.indexStatus === 'FAILED'" type="button" class="text-action" :disabled="busy" @click="retry(item)">重试索引</button></div></td></tr></tbody></table><PagePagination :page="page" :size="items.size" :total="items.total" @change="changePage" /></div>
    <ElDialog v-model="editing" :title="current ? current.title : '新建知识草稿'" width="min(920px, calc(100vw - 32px))" :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" class="ai-knowledge-dialog">
      <section class="ai-knowledge-editor"><p v-if="current?.originKind === 'CATALOG'" class="muted">这是自动同步的当前商品资料。<RouterLink :to="'/admin/products/' + current.productId + '/edit'">前往商品编辑</RouterLink>，保存后同步知识库。</p><p v-if="editorError" class="form-message-error" role="alert">{{ editorError }} <button v-if="current" type="button" class="text-action" @click="edit(current.id)">重新读取服务器草稿</button></p>
      <form @submit.prevent="save"><fieldset :disabled="busy || current?.originKind === 'CATALOG'"><div class="address-fields"><label class="form-field">标题<input v-model.trim="form.title" required maxlength="150"></label><label class="form-field">类型<select v-model="form.type" :disabled="!!current"><option v-for="(label, value) in types" :key="value" :value="value">{{ label }}</option></select></label><label v-if="form.type === 'PRODUCT'" class="form-field">关联商品<select v-model.number="form.productId" required :disabled="!!current"><option :value="null">选择商品</option><option v-if="current?.productId && !products.some(p => p.id === current!.productId)" :value="current.productId">当前关联商品</option><option v-for="item in products" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label class="form-field">资料来源<input v-model="form.sourceLabel" maxlength="150" placeholder="例如：商品资料 / 店铺售后规则"></label><label v-if="form.type === 'FAQ'" class="form-field address-field-wide">标准问法<input v-model="form.standardQuestion" required maxlength="300" placeholder="例如：草莓怎么保存？"></label><label v-if="form.type === 'FAQ'" class="form-field address-field-wide">同义问法（每行一条，最多30条）<textarea v-model="aliases" rows="3"></textarea></label><label class="form-field address-field-wide">知识正文<textarea v-model="form.body" rows="8" required maxlength="20000"></textarea></label></div></fieldset><div v-if="current?.originKind !== 'CATALOG'" class="table-actions"><button class="primary-button" :disabled="busy">{{ busy ? '正在处理…' : '保存草稿' }}</button><button v-if="current" type="button" class="secondary-button" :disabled="busy" @click="publish">发布当前已保存草稿</button><span class="field-hint">发布采用服务器已保存正文；编辑后请先保存。</span></div></form><div v-if="form.type === 'POLICY'" class="ai-policy-note"><strong>当前业务限制，编辑政策时请比较</strong><p>{{ policy }}</p></div><details v-if="current?.revisions.length"><summary>不可变修订 · {{ current.revisions.length }} 版</summary><p v-for="revision in current.revisions" :key="revision.id">第 {{ revision.version }} 版 · {{ revision.title }} · {{ date(revision.createdAt) }} {{ revision.id === current.activeRevision ? '（当前生效）' : '' }}</p></details>
      </section>
    </ElDialog>
    <section class="editor-section"><h2>检索试验</h2><p class="field-hint">仅测试当前有效知识检索，不生成回答。向量不可用时自动使用关键词。</p><form class="ai-filters" @submit.prevent="search"><input v-model="searchQuestion" required maxlength="1000" placeholder="输入标准FAQ或水果咨询问题" aria-label="检索测试问题"><button class="secondary-button" :disabled="searching">{{ searching ? '检索中…' : '测试检索' }}</button></form><p v-if="searchError" class="form-message-error">{{ searchError }}</p><template v-if="searchResult"><p class="field-hint">{{ searchResult.mode === 'HYBRID' ? '关键词与向量混合检索' : '关键词检索' }} · 命中 {{ searchResult.hits.length }} 项</p><article v-for="hit in searchResult.hits" :key="hit.source.ordinal" class="ai-search-hit"><strong>{{ hit.source.title }} · 版本 {{ hit.source.version }} {{ hit.exactFaq ? ' · 精确FAQ' : '' }}</strong><p>{{ hit.source.excerpt }}</p><small>关键词 {{ hit.keywordScore.toFixed(2) }} · 向量 {{ hit.vectorScore.toFixed(2) }}</small></article><p v-if="!searchResult.hits.length" class="muted">未找到可靠依据。检查资料是否已发布、已启用及相关内容是否准确。</p></template></section>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { ElDialog } from 'element-plus'
import PageStatus from '../components/PageStatus.vue'
import PagePagination from '../components/PagePagination.vue'
import { errorMessage, type Page } from '../api/catalog'
import * as api from '../api/admin-ai'
const types: Record<string, string> = { FRUIT: '水果知识', PRODUCT: '商品资料', FAQ: '常见问题', POLICY: '售后政策' }
const items = ref<Page<api.Knowledge> | null>(null), loading = ref(false), error = ref(''), busy = ref(false), page = ref(1), type = ref(''), keyword = ref('')
const editing = ref(false), current = ref<api.Knowledge | null>(null), editorError = ref(''), aliases = ref(''), policy = ref(''), products = ref<{ id: number; name: string; facts: string }[]>([])
const fresh = (): api.KnowledgeInput => ({ title: '', type: 'FAQ', body: '', aliases: [], sourceLabel: '管理员知识资料', standardQuestion: '', productId: null })
const form = reactive(fresh())
const searchQuestion = ref(''), searchResult = ref<Awaited<ReturnType<typeof api.searchKnowledge>> | null>(null), searching = ref(false), searchError = ref('')
const date = (value: string) => new Date(value).toLocaleString('zh-CN', { hour12: false })
const indexLabel = (value: string) => ({ DRAFT: '草稿', PENDING: '等待索引', READY: '向量已就绪', KEYWORD_ONLY: '关键词已就绪', FAILED: '索引失败' } as Record<string, string>)[value] ?? value
async function load() { loading.value = true; error.value = ''; try { items.value = await api.listKnowledge({ page: page.value, type: type.value || undefined, keyword: keyword.value || undefined }) } catch (failure) { items.value = null; current.value = null; editing.value = false; searchResult.value = null; error.value = errorMessage(failure) } finally { loading.value = false } }
function changePage(value: number) { page.value = value; void load() }
function newDocument() { editing.value = true; current.value = null; editorError.value = ''; aliases.value = ''; Object.assign(form, fresh(), { version: undefined }) }
function fill(item: api.Knowledge) { current.value = item; Object.assign(form, { title: item.title, type: item.type, body: item.body, standardQuestion: item.standardQuestion ?? '', aliases: item.aliases, sourceLabel: item.sourceLabel, productId: item.productId, version: item.version }); aliases.value = item.aliases.join('\n'); editing.value = true }
async function edit(id: number) { editorError.value = ''; try { fill(await api.getKnowledge(id)) } catch (failure) { current.value = null; editing.value = false; error.value = errorMessage(failure) } }
async function save() { busy.value = true; editorError.value = ''; try { fill(await api.saveKnowledge(current.value?.id ?? null, { ...form, aliases: aliases.value.split('\n').map(s => s.trim()).filter(Boolean) })); await load() } catch (failure) { editorError.value = errorMessage(failure) } finally { busy.value = false } }
async function publish() { if (!current.value) return; busy.value = true; editorError.value = ''; try { fill(await api.publishKnowledge(current.value.id, current.value.version)); await load() } catch (failure) { editorError.value = errorMessage(failure) } finally { busy.value = false } }
async function toggle(item: api.Knowledge) { busy.value = true; try { const updated = await api.enableKnowledge(item.id, item.version, !item.enabled); if (current.value?.id === item.id) fill(updated); await load() } catch (failure) { error.value = errorMessage(failure) } finally { busy.value = false } }
async function retry(item: api.Knowledge) { busy.value = true; try { await api.retryKnowledge(item.id, item.version); await load() } catch (failure) { error.value = errorMessage(failure) } finally { busy.value = false } }
async function search() { searching.value = true; searchError.value = ''; try { searchResult.value = await api.searchKnowledge(searchQuestion.value) } catch (failure) { searchError.value = errorMessage(failure) } finally { searching.value = false } }
watch(() => form.type, async value => { if (value === 'PRODUCT' && !products.value.length) { try { products.value = await api.knowledgeProducts() } catch (failure) { editorError.value = errorMessage(failure) } } })
onMounted(async () => { await load(); try { policy.value = await api.businessPolicy() } catch { policy.value = '暂时无法读取业务限制，请刷新后再比较政策。' } })
</script>
<style scoped>
.ai-knowledge-dialog :deep(.el-dialog__body){max-height:calc(100dvh - 190px);overflow-y:auto}
.ai-admin{max-width:1180px}.ai-filters{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:20px 0}.ai-filters input,.ai-filters select{min-width:150px;max-width:100%;border:1px solid #d7e0d2;background:white;border-radius:6px;padding:9px 11px;font:inherit;font-size:13px}.admin-table td{max-width:350px;overflow-wrap:anywhere}.admin-table small{display:block;color:#8a9682;font-size:11px;margin-top:6px}.ai-knowledge-editor fieldset{padding:0;border:0}.ai-knowledge-editor details{font-size:12px;line-height:1.9;margin-top:20px;color:#6b7b62}.ai-policy-note{padding:14px 18px;background:#faf7eb;border-left:3px solid #d5c387;margin-top:20px;font-size:12px;line-height:1.8;color:#7e7559}.ai-search-hit{padding:14px 0;border-bottom:1px solid #e6eddf;font-size:12px;line-height:1.8}.ai-search-hit p{white-space:pre-wrap;color:#73836b}.ai-search-hit small{color:#96a18e}@media(max-width:700px){.ai-filters input{flex:1;min-width:120px}.catalog-heading{gap:14px}.ai-knowledge-editor .table-actions{flex-wrap:wrap}}
</style>
